INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4402-4000-8000-000000000002', 'b1b2c3d4-4444-4000-8000-000000000004', 2, 'Oração: Contemplar o Dom', 'Agradecer pelo corpo como dom', '{"text": "Senhor Deus,\nV\u00f3s me criastes \u00e0 Vossa imagem e semelhan\u00e7a.\nMeu corpo \u00e9 templo do Esp\u00edrito Santo,\nlinguagem viva do Vosso amor.\n\nAjudai-me a contemplar meu corpo\nn\u00e3o como objeto de vergonha ou idolatria,\nmas como dom sagrado que revela\no mist\u00e9rio da comunh\u00e3o e da entrega.\n\nPurificai meu olhar,\npara que eu veja em cada pessoa\na dignidade inviol\u00e1vel de filho de Deus.\n\nS\u00e3o Jo\u00e3o Paulo II, rogai por n\u00f3s.\nAm\u00e9m.", "instruction": "Reze diante de um crucifixo, contemplando como Cristo entregou Seu corpo por amor."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;